/// `scope_flags` bits.
const GLOBAL: OptScopeFlags = 1 << kOptScopeGlobal;
const WIN: OptScopeFlags = 1 << kOptScopeWin;
const BUF: OptScopeFlags = 1 << kOptScopeBuf;

/// A row with every field at rest: a global-scoped, mutable, flagless
/// boolean that defaults to false and belongs to no scope. Each row below
/// fills in what it needs and takes the rest from here.
const BLANK: VimOption = VimOption {
    fullname: ptr::null_mut(),
    shortname: ptr::null_mut(),
    flags: 0,
    type_0: kOptValTypeBoolean,
    scope_flags: 0,
    var: OptVar::NoGlobal,
    flags_var: None,
    scope_idx: scope_idx(kGlobalOptInvalid, kWinOptInvalid, kBufOptInvalid),
    immutable: false,
    values: &[],
    opt_did_set_cb: None,
    opt_expand_cb: None,
    def_val: boolean(false),
};

const fn name(s: &'static CStr) -> *mut c_char {
    s.as_ptr().cast_mut()
}

const fn scope_idx(global: GlobalOptIndex, win: WinOptIndex, buf: BufOptIndex) -> [ssize_t; 3] {
    [global as ssize_t, win as ssize_t, buf as ssize_t]
}

const fn boolean(value: bool) -> OptVal {
    // A default is never the third state -- an option's own default is
    // always a value, never "not set in this scope".
    OptVal::Boolean(Some(value))
}

const fn number(value: OptInt) -> OptVal {
    OptVal::Number(value)
}

const fn string(value: &'static CStr) -> OptVal {
    OptVal::static_string(value)
}

/// Copy one generated part into the table under construction.
const fn fill(table: &mut [VimOption], base: usize, part: &[VimOption]) -> usize {
    let mut i = 0;
    while i < part.len() {
        table[base + i] = part[i];
        i += 1;
    }
    base + part.len()
}

/// Every option there is. A row's position is its `OptIndex`.
///
/// Immutable, and in `.rodata`: what changes about an option while
/// the editor runs lives in `crate::option::state` instead.
pub static options: ConstTable<[VimOption; kOptCount as usize]> = ConstTable::new(table());

/// The table, spliced together from the generated parts. Public to
/// the crate because `crate::option::state` seeds each option's
/// starting default from the row that declares it.
pub(crate) const fn table() -> [VimOption; kOptCount as usize] {
    let mut table = [BLANK; kOptCount as usize];
    let mut base = 0;
    base = fill(&mut table, base, &table_1::PART);
    base = fill(&mut table, base, &table_2::PART);
    base = fill(&mut table, base, &table_3::PART);
    base = fill(&mut table, base, &table_4::PART);
    base = fill(&mut table, base, &table_5::PART);
    assert!(base == kOptCount as usize);
    let mut i = 0;
    while i < table.len() {
        assert!(
            table[i].var.agrees_with(table[i].type_0),
            "an option's variable is not the type its row declares"
        );
        i += 1;
    }
    table
}
